ST.xhtml:p:
(*-----------------------通用轴1----------------------------------------*)
RTrigger1(CLK := g_biGeneral1MoveVelOpen);
IF RTrigger1.Q THEN
  g_boGeneral1_MoveVelDone :=FALSE;
  nGeneral1VelState := 10;
END_IF;
dGeneral1VelMoveVel := g_diGneral1VelMoveVel;
CASE nGeneral1VelState OF
  0:(*空闲状态*)
  nGeneral1VelState := 0;
  10:(*初始化*)
    g_General1_MoveVel.EXECUTE := FALSE;
    nGeneral1VelState := 20;
  20:(*匀速中*)
    g_General1_MoveVel.Execute := TRUE;
    g_General1_MoveVel.Direction := 1;(*1 正向；3 负向*)
    g_General1_MoveVel.Velocity := dGeneral1VelMoveVel;(*速度*)
    g_General1_MoveVel.BufferMode := 0;

    IF g_biGeneral1MoveVelStop THEN(*接收停止信号*)
      nGeneral1VelState := 30;
      g_General1_Stop.Execute :=FALSE;
    END_IF;

    IF g_bPlcPauseBuffer THEN
      nGeneral1VelState := 40; 
    END_IF;

    IF g_General1_MoveVel.CommandAborted OR g_General1_MoveVel.Error THEN
      g_General1_MoveVel.Execute := FALSE;
      g_boGeneral1_MoveVelDone :=FALSE;
      nGeneral1VelState := 0;
    END_IF;
  30:(*强制停止*)
    g_General1_MoveVel.Execute := FALSE;
    g_General1_Stop.Execute := TRUE;
    IF g_General1_Stop.Done THEN
      g_General1_Stop.Execute := FALSE;
      nGeneral1VelState := 0;
      g_boGeneral1_MoveVelDone :=TRUE;
    END_IF;

    IF g_General1_Stop.CommandAborted OR g_General1_Stop.Error THEN
      g_General1_Stop.Execute := FALSE;
      g_boGeneral1_MoveVelDone :=TRUE;
      nGeneral1VelState := 0;
    END_IF;
  40:(*暂停*)
    g_General1_MoveVel.Execute := FALSE;
    g_boGeneral1_MoveVelDone :=FALSE;
    g_General1_Stop.Execute := TRUE;
    IF g_General1_Stop.Done THEN
      nGeneral1VelState := 50;
      g_General1_Stop.Execute := FALSE;
    END_IF;
    IF g_General1_Stop.CommandAborted OR g_General1_Stop.Error THEN
      g_General1_Stop.Execute := FALSE;
      nGeneral1VelState := 0; 
    END_IF;
  50:(*等待开始*)
     IF g_bPlcStartBuffer THEN
      nGeneral1VelState := 10;    
    END_IF; 
END_CASE;
(*-----------------------通用轴2----------------------------------------*)
RTrigger2(CLK := g_biGeneral2MoveVelOpen);
IF RTrigger2.Q THEN
  g_boGeneral1_MoveVelDone :=FALSE;
  nGeneral2VelState := 10;
END_IF;
dGeneral2VelMoveVel := g_diGneral2VelMoveVel;
CASE nGeneral2VelState OF
  0:(*空闲状态*)
  nGeneral2VelState := 0;
  10:(*初始化*)
    g_General2_MoveVel.EXECUTE := FALSE;
    nGeneral2VelState := 20;
  20:(*匀速中*)
    g_General2_MoveVel.Execute := TRUE;
    g_General2_MoveVel.Direction := 1;(*1 正向；3 负向*)
    g_General2_MoveVel.Velocity := dGeneral1VelMoveVel;(*速度*)
    g_General2_MoveVel.BufferMode := 0;

    IF g_biGeneral2MoveVelStop THEN(*接收停止信号*)
      nGeneral2VelState := 30;
      g_General2_Stop.Execute :=FALSE;
    END_IF;

    IF g_bPlcPauseBuffer THEN
      nGeneral2VelState := 40; 
    END_IF;

    IF g_General2_MoveVel.CommandAborted OR g_General2_MoveVel.Error THEN
      g_General2_MoveVel.Execute := FALSE;
      nGeneral2VelState := 0;
    END_IF;
  30:(*强制停止*)
    g_General2_MoveVel.Execute := FALSE;
    g_General2_Stop.Execute := TRUE;
    IF g_General2_Stop.Done THEN
      g_General2_Stop.Execute := FALSE;
      nGeneral2VelState := 0;
      g_boGeneral2_MoveVelDone :=TRUE;
    END_IF;

    IF g_General2_Stop.CommandAborted OR g_General2_Stop.Error THEN
      g_General2_Stop.Execute := FALSE;
      g_boGeneral2_MoveVelDone :=TRUE;
      nGeneral2VelState := 0;
    END_IF;
  40:(*暂停*)
    g_boGeneral2_MoveVelDone :=FALSE;
    g_General2_MoveVel.Execute := FALSE;
    g_General2_Stop.Execute := TRUE;
    IF g_General2_Stop.Done THEN
      nGeneral2VelState := 50;
      g_General2_Stop.Execute := FALSE;
    END_IF;
    IF g_General2_Stop.CommandAborted OR g_General2_Stop.Error THEN
      g_General2_Stop.Execute := FALSE;
      g_boGeneral2_MoveVelDone :=FALSE;
      nGeneral2VelState := 0; 
    END_IF;
  50:(*等待开始*)
     IF g_bPlcStartBuffer THEN
      nGeneral2VelState := 10;    
    END_IF; 
END_CASE;
IF g_bPlcResetBuffer THEN
  nGeneral1VelState := 0; 
  nGeneral2VelState := 0; 
  g_General1_MoveVel.Execute := FALSE;
  g_General1_Stop.Execute := FALSE;
  g_General1_MoveVel.Velocity := 0.0;
  g_General2_MoveVel.Execute := FALSE;
  g_General2_Stop.Execute := FALSE;
  g_General2_MoveVel.Velocity := 0.0;
  g_boGeneral1_MoveVelDone :=FALSE;
  g_boGeneral2_MoveVelDone :=FALSE;
END_IF;
